    }
    private FileStream OpenArchive(string path, SiteRecord site, long jobId, string operation) { try { return File.OpenRead(path); } catch (Exception ex) { LogFailure(site, jobId, operation, "archive-open", path, "archive stream", ex); throw; } }
    public void ReconcileIncomplete() { _store.MarkRunningJobsForRecovery(); foreach (var site in _store.Sites().Where(x => x.Operation is not (OperationPhase.None or OperationPhase.Completed or OperationPhase.Failed or OperationPhase.RecoveryRequired))) { site.Operation = OperationPhase.RecoveryRequired; site.HealthReason = "The process restarted during deployment. Manual recovery is required; no automatic file mutation was attempted."; _store.SetRecoveryIfActive(site.Id); } }
    private async Task<(bool Success, string Message)> RunAsync(SiteRecord site, Stream upload, string originalName, string? existingArchive, CancellationToken token, long jobId, string operation)
    {
        if (!OperatingSystem.IsWindows()) return (false, "Deployment is disabled: IIS operations are Windows-only."); if (!Path.IsPathRooted(site.PhysicalPath) || !Directory.Exists(site.PhysicalPath)) return (false, "The IIS site path is unavailable."); if (!originalName.EndsWith(".zip", StringComparison.OrdinalIgnoreCase)) return (false, "Only ZIP archives are accepted."); if (_options.RetentionCount < 2 || _options.GateSuccesses < 1 || _options.GateWindowSeconds < 1 || _options.MaxUploadBytes < 1 || _options.MaxExpandedBytes < 1) return (false, "Unsafe deployment configuration.");
        if (!site.TargetAvailable) return (false, "The IIS application target is unavailable; rediscover it before deployment.");
        var sitePath = Path.GetFullPath(site.PhysicalPath); var archiveRoot = PathSafety.ResolvePrivate(_root, _options.ArchivePath); Directory.CreateDirectory(archiveRoot); if (PathSafety.IsWithin(sitePath, archiveRoot) || PathSafety.IsWithin(archiveRoot, sitePath)) return (false, "The target and private archive paths must not overlap."); var gate = _locks.GetOrAdd(jobId > 0 ? _store.Site(site.Id)?.ParentSiteId ?? site.ParentSiteId : site.ParentSiteId.Length == 0 ? site.Id : site.ParentSiteId, _ => new SemaphoreSlim(1, 1)); await gate.WaitAsync(token); string? archive = existingArchive, staging = null, snapshot = null; var operationId = $"{DateTime.UtcNow:yyyyMMddHHmmss}_{Guid.NewGuid():N}"; var wasStarted = string.Equals(site.IisState, "Started", StringComparison.OrdinalIgnoreCase); var filesMutationStarted = false;
        try
        {
            if (site.Operation is not (OperationPhase.None or OperationPhase.Staging or OperationPhase.Completed or OperationPhase.Failed)) return (false, "Another deployment operation is incomplete."); var storageToken = ApplicationTargetIdentity.StorageToken(site.Id); staging = Path.Combine(archiveRoot, $".staging_{storageToken}_{operationId}"); archive = existingArchive ?? Path.Combine(archiveRoot, $"{storageToken}_{operationId}.zip"); if (existingArchive is null) { LogPhase(site, jobId, operation, "upload-saving", $"destination={Path.GetFullPath(archive)}"); await SaveUpload(upload, archive, token, site.Id, jobId, operation); LogPhase(site, jobId, operation, "upload-saved", $"path={Path.GetFullPath(archive)}"); }
            RevalidateTarget(site); var poolPlan = _iis.ResolveDeploymentPool(site); LogPhase(site, jobId, operation, "validation-extraction-started", $"source={Path.GetFullPath(archive)} destination={Path.GetFullPath(staging)}"); ValidateAndExtract(archive, staging, site, jobId, operation); LogPhase(site, jobId, operation, "validation-extraction-completed", $"destination={Path.GetFullPath(staging)}"); snapshot = Path.Combine(archiveRoot, $".recovery_{ApplicationTargetIdentity.StorageToken(site.Id)}_{operationId}"); SetPhase(site, OperationPhase.Staging, staging, snapshot); LogPhase(site, jobId, operation, "quiescence-started", $"stopping shared pool {poolPlan.PoolName} once"); SetPhase(site, OperationPhase.Quiescing, staging, snapshot); if (!await _iis.QuiesceForDeploymentAsync(poolPlan, token)) throw new InvalidOperationException("Unable to confirm IIS application-pool shutdown; live files were not changed."); LogPhase(site, jobId, operation, "quiescence-completed", "shared pool and worker processes stopped"); RevalidateTarget(site); _iis.ResolveDeploymentPool(site); SetPhase(site, OperationPhase.Snapshot, staging, snapshot); LogPhase(site, jobId, operation, "snapshot-started", $"source={sitePath} destination={Path.GetFullPath(snapshot)}"); CopyTree(sitePath, snapshot, site, jobId, operation); LogPhase(site, jobId, operation, "snapshot-completed", $"destination={Path.GetFullPath(snapshot)}"); RevalidateTarget(site); _iis.ResolveDeploymentPool(site); SetPhase(site, OperationPhase.Deploying, staging, snapshot); filesMutationStarted = true; LogPhase(site, jobId, operation, "live-file-replace-started", $"source={Path.GetFullPath(staging)} destination={sitePath}"); ReplaceSite(sitePath, staging, _options.PreservedFolders, site, jobId, operation); LogPhase(site, jobId, operation, "live-file-replace-completed", $"destination={sitePath}"); SetPhase(site, OperationPhase.Verifying, staging, snapshot); LogPhase(site, jobId, operation, "start-health-gate-started", "restarting