            if (existingArchive is null) _store.AddArchive(new ArchiveRecord { SiteId = site.Id, Path = archive!, OriginalName = originalName, CreatedUtc = DateTimeOffset.UtcNow, Successful = true, Active = true }); else _store.SetActive(site.Id, archive!); site.ActiveArchive = archive; site.Operation = OperationPhase.Completed; site.SnapshotPath = null; site.StagingPath = null; site.HealthReason = "Deployment completed."; _store.UpdateOperation(site); _store.Retain(site.Id, _options.RetentionCount); return (true, "Deployment completed successfully.");
        }
        catch (Exception ex)
        {
