            site.Operation = OperationPhase.Restoring; site.SnapshotPath = snapshot; site.StagingPath = staging; site.HealthReason = ex.Message; _store.UpdateOperation(site); LogPhase(site, jobId, operation, "rollback-started", $"snapshot={snapshot ?? "none"}");
            try { if (filesMutationStarted) { if (snapshot is null || !Directory.Exists(snapshot)) throw new InvalidOperationException("No recovery snapshot exists."); var rollbackPlan = _iis.ResolveDeploymentPool(site); LogPhase(site, jobId, operation, "rollback-re-quiescence-started", "stopping shared pool before restore"); if (!await _iis.QuiesceForDeploymentAsync(rollbackPlan, CancellationToken.None)) throw new InvalidOperationException("Rollback stopped: IIS shutdown could not be confirmed; recovery snapshot was preserved."); LogPhase(site, jobId, operation, "rollback-re-quiescence-completed", "shared pool and worker processes stopped"); RevalidateTarget(site); ReplaceSite(sitePath, snapshot, _options.PreservedFolders, site, jobId, operation); if (wasStarted && !await StartAndGateAsync(site, rollbackPlan, CancellationToken.None, jobId, operation)) throw new InvalidOperationException("Rollback/start verification failed: the shared application pool or required application health checks failed."); } LogPhase(site, jobId, operation, "rollback-recovery-completed", "original site and shared application pool restored and health verified"); site.Operation = OperationPhase.Failed; site.SnapshotPath = null; site.StagingPath = null; site.HealthReason = $"Deployment failed and rollback verified: {ex.Message}"; _store.UpdateOperation(site); return (false, site.HealthReason); }
            catch (Exception rollback) { _logger.LogCritical(rollback, "Rollback failed for site {SiteId}; job {JobId}; operation {Operation}; manual recovery is required", site.Id, jobId, operation); site.Operation = OperationPhase.RecoveryRequired; site.HealthReason = $"Manual recovery required. Deployment: {ex.Message}; rollback: {rollback.Message}"; _store.UpdateOperation(site); return (false, site.HealthReason); }
